// PhishSense game logic (runs in the browser)

const ROUNDS = 5;        // rounds per mode
const TO_PASS = 4;       // correct answers needed for the badge
const PER_CORRECT = 100; // points per correct answer
const BADGES = { easy: "🐟 Minnow", medium: "🎣 Angler", hard: "⚓ Captain" };
const ALL_MODES = ["easy", "medium", "hard"];
const MISSIONS = {
  easy: "Warm-up shift. These scams are obvious: watch for typos, surprise prizes, and ALL CAPS urgency.",
  medium: "Scammers are getting smarter. Check every sender address and phone number against the real ones above.",
  hard: "Expert level. Some scams look perfect, and some real emails look scary. Read every detail before you decide.",
};

let mode, round, correct, current, seen;
let results;  // one entry per round: true (correct) or false (wrong)
let streak;   // correct answers in a row, resets on a wrong answer
let missed;   // every red flag from the rounds the player got wrong

const $ = (id) => document.getElementById(id);
const show = (id) => {
  ["start-screen", "mission-screen", "play-screen", "end-screen"].forEach((s) => $(s).classList.add("hidden"));
  $(id).classList.remove("hidden");
};
const esc = (t) => String(t ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

// Players who ask for less motion get the same game with the animations off.
const calmMode = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// ---------- Talking to the backend ----------
// Practice mode: if the backend isn't running (opened as a file, Live Server,
// or a static host like Vercel), the game uses mock-data.js instead.
let OFFLINE = location.protocol === "file:";

async function checkBackend() {
  if (OFFLINE) return;
  try {
    const r = await fetch("/api/leaderboard");
    if (!r.ok) throw new Error("no backend");
    await r.json();
  } catch (e) {
    OFFLINE = true;
  }
}

async function apiGetScenario(mode, seen) {
  if (OFFLINE) {
    const pool = MOCK_SCENARIOS.filter((s) => s.difficulty === mode && !seen.includes(s.scenario_id));
    const s = pool[Math.floor(Math.random() * pool.length)];
    return { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
  }
  return fetch(`/api/scenario?mode=${mode}&seen=${seen.join(",")}`).then((r) => r.json());
}

async function apiAnswer(scenario_id, guess) {
  if (OFFLINE) {
    const s = MOCK_SCENARIOS.find((x) => x.scenario_id === scenario_id);
    return { correct: guess === s.game_answer, game_answer: s.game_answer, red_flags: s.red_flags, explanation: s.explanation };
  }
  return fetch("/api/answer", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ scenario_id, guess }),
  }).then((r) => r.json());
}

async function apiSaveScore(username, points, badge) {
  if (OFFLINE) {
    const board = JSON.parse(localStorage.getItem("ps-board") || "{}");
    const p = board[username] || { username, total_score: 0, badges: [] };
    p.total_score += points;
    if (badge && !p.badges.includes(badge)) p.badges.push(badge);
    board[username] = p;
    try { localStorage.setItem("ps-board", JSON.stringify(board)); } catch (e) {}
    return p;
  }
  return fetch("/api/score", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, points, badge }),
  }).then((r) => r.json());
}

async function apiLeaderboard() {
  if (OFFLINE) {
    let board = {};
    try { board = JSON.parse(localStorage.getItem("ps-board") || "{}"); } catch (e) {}
    return Object.values(board)
      .sort((a, b) => b.badges.length - a.badges.length || b.total_score - a.total_score)
      .slice(0, 10);
  }
  return fetch("/api/leaderboard").then((r) => r.json());
}

// ---------- Start: pick a difficulty, then see the mission ----------
document.querySelectorAll(".mode").forEach((btn) =>
  btn.addEventListener("click", () => {
    if (!$("username").value.trim()) return $("username").focus();
    mode = btn.dataset.mode;
    const label = mode.charAt(0).toUpperCase() + mode.slice(1);
    $("mission-mode").textContent = `${label} mode · ${BADGES[mode]} badge`;
    $("mission-tip").textContent = MISSIONS[mode];
    show("mission-screen");
  })
);

$("btn-back").addEventListener("click", () => show("start-screen"));

$("btn-start").addEventListener("click", () => {
  round = 0;
  correct = 0;
  seen = [];
  results = [];
  streak = 0;
  missed = [];
  $("recap").classList.add("hidden");
  $("badge-reveal").classList.add("hidden");
  $("confetti").innerHTML = "";
  show("play-screen");
  nextRound();
});

// ---------- Progress dots + streak ----------
function renderDots() {
  let html = "";
  for (let i = 0; i < ROUNDS; i++) {
    let cls = "";
    if (results[i] === true) cls = "correct";
    else if (results[i] === false) cls = "wrong";
    else if (i === round - 1) cls = "current";
    html += `<span class="dot ${cls}"></span>`;
  }
  $("dots").innerHTML = html;
  $("dots").setAttribute("aria-label", `Round ${Math.min(round, ROUNDS)} of ${ROUNDS}, ${correct} correct`);
}

function renderStreak() {
  $("streak").textContent =
    streak >= 2 ? `🔥 ${streak} in a row` : streak === 1 ? "🔥 1 correct" : "";
}

// ---------- Play ----------
async function nextRound() {
  await ready;
  round++;
  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
  $("result").classList.add("hidden");
  $("btn-next").classList.add("hidden");
  $("btn-phish").disabled = $("btn-legit").disabled = true;
  $("message").className = "card";   // clears the glow or shake from the last round
  $("pop-layer").innerHTML = "";
  hidePeek();
  renderDots();
  renderStreak();
  $("message").innerHTML = `<p class="loading">Loading message...</p>`;

  current = await apiGetScenario(mode, seen);
  seen.push(current.scenario_id);
  $("message").innerHTML = renderMessage(current);
  $("btn-phish").disabled = $("btn-legit").disabled = false;
}

// A steady clock time per scenario, so the inbox and phone look real
// without the time jumping around every time you re-read a message.
function clockFor(s) {
  const id = Math.abs(Number(s.scenario_id) || 0);
  const hour24 = 8 + ((id * 3) % 9);          // 8 AM to 4 PM
  const minute = String((id * 17) % 60).padStart(2, "0");
  const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12;
  return { short: `${hour12}:${minute}`, long: `${hour12}:${minute} ${hour24 < 12 ? "AM" : "PM"}` };
}

const initialOf = (sender) => {
  const m = String(sender || "").match(/[a-z]/i);
  return m ? m[0].toUpperCase() : "?";
};

// ---------- Hover to inspect links ----------
// Emails hide the real address behind friendly text, the way real phishing
// does. Hovering (or tapping) shows where the link really goes. The link is a
// plain button, so it can never open anything.
const LINK_LABELS = [
  [/\.exe|download|update/i, "Download the update"],
  [/claim|winner|prize|reward/i, "Claim your reward"],
  [/sign-?in|log-?in/i, "Sign in to your account"],
  [/verify/i, "Verify your account"],
  [/confirm/i, "Confirm now"],
  [/billing|invoice|payment/i, "View billing details"],
  [/video|watch/i, "Watch now"],
  [/story|news|article/i, "Read the full story"],
];

function parseLink(raw) {
  const text = String(raw || "").trim();
  try {
    const u = new URL(/^[a-z]+:\/\//i.test(text) ? text : `http://${text}`);
    const host = u.hostname;
    const parts = host.split(".");
    const domain = parts.length > 2 ? parts.slice(-2).join(".") : host;
    return {
      scheme: `${u.protocol}//`,
      sub: host.slice(0, host.length - domain.length), // e.g. "newsnow.com."
      domain,                                          // the site you really land on
      rest: u.pathname === "/" && !u.search ? "" : u.pathname + u.search,
    };
  } catch (e) {
    return { scheme: "", sub: "", domain: text, rest: "" };
  }
}

function linkLabel(s) {
  if (s.link_text) return s.link_text;
  const { rest } = parseLink(s.link);
  const hit = LINK_LABELS.find(([re]) => re.test(rest)) || LINK_LABELS.find(([re]) => re.test(s.link));
  return hit ? hit[1] : "Open link";
}

function renderLink(s) {
  if (!s.link) return "";
  const hint = `<span class="link-hint"><span class="hint-hover">Hover</span><span class="hint-tap">Tap</span> to inspect</span>`;
  if (s.channel === "sms") {
    // Texts show the raw address, but tapping it still previews the real site.
    return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">${esc(s.link)}</button>${hint}</p>`;
  }
  return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">🔗 ${esc(linkLabel(s))}</button>${hint}</p>`;
}

const peek = document.createElement("div");
peek.id = "link-peek";
peek.className = "link-peek";
peek.setAttribute("role", "tooltip");
peek.hidden = true;
document.body.appendChild(peek);

let peekFor = null;     // the link the popup belongs to
let peekPinned = false; // true after a tap or click, so it stays open

function showPeek(chip) {
  const p = parseLink(chip.dataset.href);
  peek.innerHTML = `
    <p class="peek-title">🔍 This link really goes to:</p>
    <p class="peek-url">${esc(p.scheme)}${p.sub ? `<span class="peek-sub">${esc(p.sub)}</span>` : ""}<b class="peek-domain">${esc(p.domain)}</b>${esc(p.rest)}</p>
    <p class="peek-tip">The real site is the last part of the address, right before the first /</p>`;
  peek.hidden = false;
  if (peekFor && peekFor !== chip) peekFor.removeAttribute("aria-describedby");
  peekFor = chip;
  chip.setAttribute("aria-describedby", "link-peek");
  placePeek();
}

function hidePeek() {
  peek.hidden = true;
  peekPinned = false;
  if (peekFor) peekFor.removeAttribute("aria-describedby");
  peekFor = null;
}

// Always open ABOVE the link, so it never covers the Phish / Legit buttons
// below the message. If the link is too close to the top of the screen,
// scroll up just enough to make room.
function placePeek() {
  if (!peekFor || peek.hidden) return;
  if (!document.body.contains(peekFor)) return hidePeek();
  const gap = 8, edge = 12;
  const w = peek.offsetWidth, h = peek.offsetHeight;
  let r = peekFor.getBoundingClientRect();
  const short = edge - (r.top - gap - h);
  if (short > 0 && window.scrollY > 0) {
    window.scrollBy(0, -Math.min(short, window.scrollY));
    r = peekFor.getBoundingClientRect();
  }
  const top = Math.max(edge, r.top - gap - h);
  const left = Math.min(Math.max(edge, r.left), window.innerWidth - w - edge);
  peek.style.top = `${top}px`;
  peek.style.left = `${Math.max(edge, left)}px`;
}

const chipFrom = (e) => e.target.closest?.(".link-chip");

document.addEventListener("mouseover", (e) => {
  const chip = chipFrom(e);
  if (chip && !peekPinned) showPeek(chip);
});
document.addEventListener("mouseout", (e) => {
  const chip = chipFrom(e);
  if (chip && !peekPinned && !chip.contains(e.relatedTarget)) hidePeek();
});
document.addEventListener("focusin", (e) => {
  const chip = chipFrom(e);
  if (chip) showPeek(chip);
});
document.addEventListener("focusout", (e) => {
  if (chipFrom(e) && !peekPinned) hidePeek();
});
document.addEventListener("click", (e) => {
  const chip = chipFrom(e);
  if (chip) {
    e.preventDefault();
    if (peekPinned && peekFor === chip) return hidePeek();
    showPeek(chip);
    peekPinned = true;
  } else if (peekPinned && !peek.contains(e.target)) {
    hidePeek();
  }
});
document.addEventListener("keydown", (e) => { if (e.key === "Escape") hidePeek(); });
window.addEventListener("scroll", placePeek, { passive: true });
window.addEventListener("resize", placePeek);

function renderMessage(s) {
  const link = renderLink(s);
  const clock = clockFor(s);

  if (s.channel === "sms") {
    return `<div class="sms">
      <div class="status-bar">
        <span class="sb-time">${esc(clock.short)}</span>
        <span class="sb-right">
          <span class="signal" aria-hidden="true"><i></i><i></i><i></i><i></i></span>
          <span class="battery" aria-hidden="true"><span class="bat-fill"></span></span>
        </span>
      </div>
      <p class="label">💬 Text message from <b>${esc(s.sender)}</b></p>
      <p class="bubble">${esc(s.body)}</p>${link}</div>`;
  }

  return `<div class="email">
    <div class="email-head">
      <div class="avatar" aria-hidden="true">${esc(initialOf(s.sender))}</div>
      <div class="email-who">
        <p class="from"><b>From:</b> ${esc(s.sender)}</p>
        <p class="subject">${esc(s.subject || "(no subject)")}</p>
      </div>
      <p class="email-time">${esc(clock.long)}</p>
    </div>
    <p class="body">${esc(s.body)}</p>${link}
    <div class="email-actions">
      <button type="button" disabled>↩ Reply</button>
      <button type="button" disabled>↪ Forward</button>
    </div>
  </div>`;
}

// Red flags arrive as one string with semicolons between them.
function flagList(red_flags) {
  const parts = Array.isArray(red_flags) ? red_flags : String(red_flags || "").split(";");
  return parts.map((f) => String(f).trim()).filter(Boolean);
}

function floatScore(text) {
  if (calmMode()) return;
  const bit = document.createElement("span");
  bit.className = "pop-score";
  bit.textContent = text;
  $("pop-layer").appendChild(bit);
  setTimeout(() => bit.remove(), 1500);
}

async function answer(guess) {
  $("btn-phish").disabled = $("btn-legit").disabled = true;
  const r = await apiAnswer(current.scenario_id, guess);

  results[round - 1] = !!r.correct;
  if (r.correct) {
    correct++;
    streak++;
    $("message").classList.add("is-correct");
    floatScore(`+${PER_CORRECT}`);
  } else {
    streak = 0;
    $("message").classList.add("is-wrong");
    flagList(r.red_flags).forEach((f) => missed.push(f));
  }
  renderDots();
  renderStreak();

  const flags = r.red_flags
    ? `<p><b>Red flags:</b></p><ul>${flagList(r.red_flags).map((f) => `<li>${esc(f)}</li>`).join("")}</ul>`
    : "";
  const went = current.link
    ? `<p class="link-reveal">🔍 That link really went to <b>${esc(parseLink(current.link).domain)}</b></p>`
    : "";
  $("result").innerHTML = `
    <h3>${r.correct ? "✅ Correct!" : "❌ Not quite."} This one was <b>${r.game_answer}</b>.</h3>
    ${flags}<p>${esc(r.explanation)}</p>${went}`;
  $("result").className = `card ${r.correct ? "good" : "bad"}`;
  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
  $("btn-next").textContent = round < ROUNDS ? "Next" : "See results";
  $("btn-next").classList.remove("hidden");
}

$("btn-phish").addEventListener("click", () => answer("Phish"));
$("btn-legit").addEventListener("click", () => answer("Legit"));
$("btn-next").addEventListener("click", () => (round < ROUNDS ? nextRound() : finish()));

// ---------- Badge reveal ----------
const CONFETTI_COLORS = ["#2de0c4", "#3ddc84", "#ffd166", "#ff5d6c", "#8ecae6", "#ffffff"];

// Replays a CSS animation that has already run once this session.
function replayAnimation(el) {
  el.style.animation = "none";
  void el.offsetWidth;
  el.style.animation = "";
}

function burstConfetti() {
  const layer = $("confetti");
  layer.innerHTML = "";
  if (calmMode()) return;
  for (let i = 0; i < 30; i++) {
    const bit = document.createElement("span");
    bit.className = "confetti-bit";
    bit.style.left = `${Math.random() * 100}%`;
    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
    bit.style.setProperty("--dx", `${(Math.random() - 0.5) * 240}px`);
    bit.style.setProperty("--rot", `${Math.random() * 900 - 450}deg`);
    bit.style.animationDelay = `${Math.random() * 0.35}s`;
    bit.style.animationDuration = `${1.5 + Math.random()}s`;
    if (i % 3 === 0) bit.style.borderRadius = "50%";
    layer.appendChild(bit);
  }
  setTimeout(() => { layer.innerHTML = ""; }, 3200);
}

function revealBadge(isMaster) {
  const [icon, ...name] = BADGES[mode].split(" ");
  $("badge-art").textContent = icon;
  $("badge-name").textContent = name.join(" ");
  $("badge-reveal").classList.remove("hidden");
  replayAnimation($("badge-art"));
  replayAnimation($("badge-name"));

  if (isMaster) {
    $("badge-master").textContent = "🏆 PhishSense Master: all three badges earned!";
    $("badge-master").classList.remove("hidden");
    replayAnimation($("badge-master"));
  } else {
    $("badge-master").classList.add("hidden");
  }
  burstConfetti();
}

// ---------- End of run ----------
function renderRecap() {
  // Group the same red flag together so repeats show as a count.
  const groups = new Map();
  missed.forEach((flag) => {
    const key = flag.toLowerCase().replace(/\s+/g, " ");
    const hit = groups.get(key);
    if (hit) hit.n++;
    else groups.set(key, { text: flag, n: 1 });
  });
  const items = [...groups.values()].sort((a, b) => b.n - a.n);

  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
    : `<p class="clean">You caught every red flag!</p>`);
  $("recap").classList.remove("hidden");
}

async function finish() {
  const passed = correct >= TO_PASS;
  const badge = passed ? mode : null;
  const player = await apiSaveScore($("username").value.trim(), correct * PER_CORRECT, badge);

  const owned = Array.isArray(player?.badges) ? player.badges : (passed ? [mode] : []);
  const isMaster = ALL_MODES.every((m) => owned.includes(m));

  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
  $("end-text").textContent = passed
    ? "Nice catch. Try the next mode!"
    : `You need ${TO_PASS} to earn ${BADGES[mode]}. Every round is new, so try again!`;

  if (passed) revealBadge(isMaster);
  else $("badge-reveal").classList.add("hidden");

  renderRecap();
  show("end-screen");
  loadLeaderboard();
}

$("btn-home").addEventListener("click", () => show("start-screen"));

// ---------- Leaderboard ----------
async function loadLeaderboard() {
  const rows = await apiLeaderboard();
  $("leaderboard").innerHTML = rows.length
    ? rows.map((p) => {
        const icons = p.badges.map((b) => BADGES[b]?.split(" ")[0] || "").join(" ");
        const master = ALL_MODES.every((b) => p.badges.includes(b)) ? " 🏆" : "";
        return `<li><b>${esc(p.username)}</b> ${icons}${master} <span>${p.total_score} pts</span></li>`;
      }).join("")
    : '<li class="empty">No scores yet. Be the first!</li>';
}

const ready = checkBackend();
ready.then(loadLeaderboard);
=====STYLE=====
/* PhishSense colors: navy + teal, matching the logo */
:root {
  --navy: #0a1a33;
  --navy-2: #123a5c;
  --teal: #2de0c4;
  --text: #e9f1f7;
  --muted: #9fb7c9;
  --red: #ff5d6c;
  --green: #3ddc84;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Inter", Arial, sans-serif;
  background: var(--navy);
  color: var(--text);
}

header { text-align: center; padding: 32px 16px 8px; }
header h1 { margin: 0; font-size: 44px; font-weight: 800; }
header h1 span { color: var(--teal); }
.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }

main { max-width: 640px; margin: 0 auto; padding: 16px; }
.hidden { display: none !important; }

/* Start screen */
.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
.step-label + input { margin-top: 0; }

/* Mission screen */
.briefing { margin-top: 8px; line-height: 1.6; color: var(--muted); }
.briefing p { margin: 0 0 10px; }
.briefing p:last-child { margin-bottom: 0; }
.briefing b { color: var(--text); }
.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
.mission-buttons { display: flex; justify-content: space-between; gap: 12px; }
button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }

input {
  display: block; width: 100%; margin: 0; padding: 12px;
  border-radius: 10px; border: 1px solid var(--navy-2);
  background: var(--navy-2); color: var(--text); font-size: 16px;
}

button {
  font-family: inherit; font-size: 16px; font-weight: 600; cursor: pointer;
  border: none; border-radius: 10px; padding: 12px 18px;
  background: var(--teal); color: var(--navy);
}
button:disabled { opacity: 0.5; cursor: default; }

.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mode { padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--teal); }
.mode small { color: var(--muted); font-weight: 400; }

.card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
.card.good { border-left: 6px solid var(--green); }
.card.bad { border-left: 6px solid var(--red); }

#progress { text-align: center; color: var(--muted); }
.loading { color: var(--muted); text-align: center; }

/* ---------- Run status: progress dots + streak ---------- */
.run-bar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; min-height: 26px; margin-top: 4px;
}
.dots { display: flex; gap: 8px; }
.dot {
  width: 14px; height: 14px; border-radius: 50%;
  background: transparent; border: 2px solid #2b4a68;
  transition: background 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
}
.dot.current { border-color: var(--teal); transform: scale(1.2); }
.dot.correct { background: var(--green); border-color: var(--green); animation: dot-pop 0.4s ease; }
.dot.wrong { background: var(--red); border-color: var(--red); animation: dot-pop 0.4s ease; }

.streak { margin: 0; font-size: 14px; font-weight: 600; color: var(--teal); white-space: nowrap; }

/* ---------- Message area: glow, shake, floating score ---------- */
.message-wrap { position: relative; }
.pop-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
.pop-score {
  position: absolute; left: 50%; top: 24%;
  font-size: 40px; font-weight: 800; color: var(--green);
  text-shadow: 0 2px 12px rgba(10, 26, 51, 0.8);
  animation: float-up 1.3s ease-out forwards;
}

#message.is-correct .email,
#message.is-correct .sms { animation: glow-green 1.1s ease-out; }
#message.is-wrong { animation: shake 0.45s ease-in-out; }

@keyframes dot-pop {
  0% { transform: scale(0.6); }
  60% { transform: scale(1.35); }
  100% { transform: scale(1); }
}
@keyframes float-up {
  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.8); }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -96px) scale(1); }
}
@keyframes glow-green {
  0% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
  28% { box-shadow: 0 0 0 4px var(--green), 0 0 38px 10px rgba(61, 220, 132, 0.55); }
  100% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
}
@keyframes shake {
  10%, 90% { transform: translateX(-3px); }
  20%, 80% { transform: translateX(5px); }
  30%, 50%, 70% { transform: translateX(-9px); }
  40%, 60% { transform: translateX(9px); }
}

/* ---------- Email: looks like an inbox message ---------- */
#message.card { padding: 0; background: none; }
.email {
  background: #f7f9fb; color: #1b2a3a;
  border-radius: 14px; overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
.email::before {
  content: "INBOX";
  display: block; padding: 10px 18px;
  background: #dfe7ee; color: #45566a;
  font-size: 13px; font-weight: 600; letter-spacing: 1px;
}
.email-head {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 14px 16px; border-bottom: 1px solid #e3e9ef;
}
.avatar {
  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
  background: var(--navy-2); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 800;
}
.email-who { flex: 1 1 auto; min-width: 0; }
.email-who .from { margin: 0; font-size: 14px; color: #5b6b7b; overflow-wrap: anywhere; }
.email-who .from b { color: #1b2a3a; }
.email-who .subject { margin: 3px 0 0; font-size: 15px; font-weight: 600; color: #1b2a3a; overflow-wrap: anywhere; }
.email-time { flex: 0 0 auto; margin: 2px 0 0; font-size: 12px; color: #7b8a99; white-space: nowrap; }

.email .body { margin: 0; padding: 18px; line-height: 1.6; }

.email-actions {
  display: flex; gap: 10px;
  padding: 12px 16px; border-top: 1px solid #e3e9ef; background: #eef3f7;
}
.email-actions button,
.email-actions button:disabled {
  font-size: 14px; padding: 8px 16px; border-radius: 8px;
  background: #e1e8ee; color: #9aa8b5; border: 1px solid #d3dce4;
  opacity: 1; cursor: not-allowed;
}

/* ---------- Text message: looks like a phone ---------- */
.sms {
  width: 320px; max-width: 100%; margin: 0 auto; padding: 14px 16px 28px;
  background: #101826; border: 3px solid #2b3a4f; border-radius: 36px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
.sms::before {
  content: ""; display: block; width: 90px; height: 6px;
  margin: 0 auto 12px; background: #2b3a4f; border-radius: 3px;
}

/* Phone status bar: time, signal bars, battery */
.status-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 4px 14px; font-size: 13px; font-weight: 600; color: var(--text);
}
.sb-right { display: flex; align-items: center; gap: 7px; }
.signal { display: flex; align-items: flex-end; gap: 2px; height: 11px; }
.signal i { width: 3px; background: var(--text); border-radius: 1px; }
.signal i:nth-child(1) { height: 4px; }
.signal i:nth-child(2) { height: 6px; }
.signal i:nth-child(3) { height: 9px; }
.signal i:nth-child(4) { height: 11px; }
.battery {
  position: relative; width: 25px; height: 13px;
  border: 1.5px solid var(--text); border-radius: 3px; padding: 2px;
}
.battery::after {
  content: ""; position: absolute; right: -4px; top: 3.5px;
  width: 2px; height: 5px; background: var(--text); border-radius: 0 2px 2px 0;
}
.bat-fill { display: block; height: 100%; width: 72%; background: var(--green); border-radius: 1px; }

.sms .label { text-align: center; font-size: 13px; color: var(--muted); margin: 0 0 14px; }
.sms .label b { display: block; font-size: 16px; color: var(--text); }
.bubble {
  background: #e9edf2; color: #1b2a3a;
  padding: 12px 14px; border-radius: 18px 18px 18px 4px;
  line-height: 1.5; margin: 0; max-width: 85%;
}

/* Links are buttons on purpose: they only preview, never open anything */
.link {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px;
  margin: 0; padding: 0 18px 18px;
}
.link-chip,
.link-chip:hover {
  font: inherit; font-weight: 600; text-align: left;
  padding: 0; margin: 0; border: 0; border-radius: 3px;
  background: none; color: #1a5fd0;
  text-decoration: underline; text-underline-offset: 3px;
  cursor: help; transform: none; box-shadow: none;
  overflow-wrap: anywhere;
}
.link-chip:focus-visible { outline: 2px solid #1a5fd0; outline-offset: 3px; }
.link-hint {
  font-size: 12px; font-weight: 600; color: #7b8a99;
  padding: 2px 8px; border-radius: 999px; background: #e7edf2;
}
.hint-tap { display: none; }
@media (hover: none) {
  .hint-hover { display: none; }
  .hint-tap { display: inline; }
}
.sms .link { padding: 10px 0 0; }
.sms .link-chip { font-family: monospace; font-weight: 400; color: var(--teal); }
.sms .link-chip:focus-visible { outline-color: var(--teal); }
.sms .link-hint { background: #1d2a3d; color: var(--muted); }

/* The popup that shows a link's real destination */
.link-peek {
  position: fixed; z-index: 1000;
  width: max-content; max-width: min(360px, calc(100vw - 24px));
  padding: 10px 12px; border-radius: 10px;
  background: #0d1b2e; color: var(--text);
  border: 1px solid #2b3a4f;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
  font-size: 13px; line-height: 1.45;
  animation: peek-in 0.12s ease-out;
}
.link-peek p { margin: 0; }
.peek-title { color: var(--muted); font-weight: 600; margin-bottom: 4px !important; }
.peek-url { font-family: monospace; font-size: 14px; overflow-wrap: anywhere; color: #c9d6e2; }
.peek-sub { color: inherit; }
.peek-domain { color: #ffd166; background: rgba(255, 209, 102, 0.12); padding: 0 2px; border-radius: 3px; }
.peek-tip { margin-top: 6px !important; color: var(--muted); font-size: 12px; }
.peek-tip b { color: var(--text); }
@keyframes peek-in {
  from { opacity: 0; transform: translateY(4px); }
}
.link-reveal { margin-bottom: 0; }

.answers { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.answer.phish { background: var(--red); color: white; }
.answer.legit { background: var(--green); color: var(--navy); }

#btn-next, #btn-home { display: block; margin: 0 auto; }
#end-screen { text-align: center; }

/* ---------- Badge reveal ---------- */
.badge-reveal { position: relative; padding: 10px 0 2px; }
.badge-art {
  font-size: 96px; line-height: 1.1;
  animation: badge-drop 1.1s cubic-bezier(0.2, 0.75, 0.3, 1) both;
}
.badge-name {
  margin: 2px 0 0; font-size: 26px; font-weight: 800; color: var(--teal);
  animation: fade-rise 0.5s ease-out 0.75s both;
}
.badge-master {
  display: inline-block; margin: 14px 0 0; padding: 8px 16px;
  border: 2px solid var(--teal); border-radius: 999px;
  background: rgba(45, 224, 196, 0.1);
  font-weight: 700; color: var(--text);
  animation: fade-rise 0.5s ease-out 1.1s both;
}

