257	// Always open ABOVE the link, so it never covers the Phish / Legit buttons
258	// below the message. If the link is too close to the top of the screen,
259	// scroll up just enough to make room.
260	function placePeek() {
261	  if (!peekFor || peek.hidden) return;
262	  if (!document.body.contains(peekFor)) return hidePeek();
263	  const gap = 8, edge = 12;
264	  const w = peek.offsetWidth, h = peek.offsetHeight;
265	  let r = peekFor.getBoundingClientRect();
266	  const short = edge - (r.top - gap - h);
267	  if (short > 0 && window.scrollY > 0) {
268	    window.scrollBy(0, -Math.min(short, window.scrollY));
269	    r = peekFor.getBoundingClientRect();
270	  }
271	  const top = Math.max(edge, r.top - gap - h);
272	  const left = Math.min(Math.max(edge, r.left), window.innerWidth - w - edge);
273	  peek.style.top = `${top}px`;
274	  peek.style.left = `${Math.max(edge, left)}px`;
275	}
