279	document.addEventListener("mouseover", (e) => {
280	  const chip = chipFrom(e);
281	  if (chip && !peekPinned) showPeek(chip);
282	});
283	document.addEventListener("mouseout", (e) => {
284	  const chip = chipFrom(e);
285	  if (chip && !peekPinned && !chip.contains(e.relatedTarget)) hidePeek();
286	});
287	document.addEventListener("focusin", (e) => {
288	  const chip = chipFrom(e);
289	  if (chip) showPeek(chip);
290	});
291	document.addEventListener("focusout", (e) => {
292	  if (chipFrom(e) && !peekPinned) hidePeek();
293	});
294	document.addEventListener("click", (e) => {
295	  const chip = chipFrom(e);
296	  if (chip) {
297	    e.preventDefault();
298	    if (peekPinned && peekFor === chip) return hidePeek();
299	    showPeek(chip);
300	    peekPinned = true;
301	  } else if (peekPinned && !peek.contains(e.target)) {
302	    hidePeek();
303	  }
304	});
305	document.addEventListener("keydown", (e) => { if (e.key === "Escape") hidePeek(); });
306	window.addEventListener("scroll", placePeek, { passive: true });
307	window.addEventListener("resize", placePeek);
