384	    ${flags}<p>${esc(r.explanation)}</p>${went}`;
385	  $("result").className = `card ${r.correct ? "good" : "bad"}`;
386	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
387	  $("btn-next").textContent = round < ROUNDS ? "Next" : "See results";
388	  $("btn-next").classList.remove("hidden");
