396	const CONFETTI_COLORS = ["#2de0c4", "#3ddc84", "#ffd166", "#ff5d6c", "#8ecae6", "#ffffff"];
397	
398	// Replays a CSS animation that has already run once this session.
399	function replayAnimation(el) {
400	  el.style.animation = "none";
401	  void el.offsetWidth;
402	  el.style.animation = "";
403	}
