405	function burstConfetti() {
406	  const layer = $("confetti");
407	  layer.innerHTML = "";
408	  if (calmMode()) return;
409	  for (let i = 0; i < 30; i++) {
410	    const bit = document.createElement("span");
411	    bit.className = "confetti-bit";
412	    bit.style.left = `${Math.random() * 100}%`;
413	    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
414	    bit.style.setProperty("--dx", `${(Math.random() - 0.5) * 240}px`);
415	    bit.style.setProperty("--rot", `${Math.random() * 900 - 450}deg`);
416	    bit.style.animationDelay = `${Math.random() * 0.35}s`;
417	    bit.style.animationDuration = `${1.5 + Math.random()}s`;
418	    if (i % 3 === 0) bit.style.borderRadius = "50%";
419	    layer.appendChild(bit);
420	  }
421	  setTimeout(() => { layer.innerHTML = ""; }, 3200);
422	}
