424	function revealBadge(isMaster) {
425	  const [icon, ...name] = BADGES[mode].split(" ");
426	  $("badge-art").textContent = icon;
427	  $("badge-name").textContent = name.join(" ");
428	  $("badge-reveal").classList.remove("hidden");
429	  replayAnimation($("badge-art"));
430	  replayAnimation($("badge-name"));
431	
432	  if (isMaster) {
433	    $("badge-master").textContent = "🏆 PhishSense Master: all three badges earned!";
434	    $("badge-master").classList.remove("hidden");
435	    replayAnimation($("badge-master"));
436	  } else {
437	    $("badge-master").classList.add("hidden");
438	  }
439	  burstConfetti();
440	}
