442	// ---------- End of run ----------
443	function renderRecap() {
444	  // Group the same red flag together so repeats show as a count.
445	  const groups = new Map();
446	  missed.forEach((flag) => {
447	    const key = flag.toLowerCase().replace(/\s+/g, " ");
448	    const hit = groups.get(key);
449	    if (hit) hit.n++;
450	    else groups.set(key, { text: flag, n: 1 });
451	  });
452	  const items = [...groups.values()].sort((a, b) => b.n - a.n);
453	
454	  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
455	    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
456	    : `<p class="clean">You caught every red flag!</p>`);
457	  $("recap").classList.remove("hidden");
458	}
