460	async function finish() {
461	  const passed = correct >= TO_PASS;
462	  const badge = passed ? mode : null;
463	  const player = await apiSaveScore($("username").value.trim(), correct * PER_CORRECT, badge);
464	
465	  const owned = Array.isArray(player?.badges) ? player.badges : (passed ? [mode] : []);
466	  const isMaster = ALL_MODES.every((m) => owned.includes(m));
467	
468	  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
469	  $("end-text").textContent = passed
470	    ? "Nice catch. Try the next mode!"
471	    : `You need ${TO_PASS} to earn ${BADGES[mode]}. Every round is new, so try again!`;
472	
473	  if (passed) revealBadge(isMaster);
474	  else $("badge-reveal").classList.add("hidden");
475	
476	  renderRecap();
477	  show("end-screen");
478	  loadLeaderboard();
479	}
