483	// ---------- Leaderboard ----------
484	async function loadLeaderboard() {
485	  const rows = await apiLeaderboard();
486	  $("leaderboard").innerHTML = rows.length
487	    ? rows.map((p) => {
488	        const icons = p.badges.map((b) => BADGES[b]?.split(" ")[0] || "").join(" ");
489	        const master = ALL_MODES.every((b) => p.badges.includes(b)) ? " 🏆" : "";
490	        return `<li><b>${esc(p.username)}</b> ${icons}${master} <span>${p.total_score} pts</span></li>`;
491	      }).join("")
492	    : '<li class="empty">No scores yet. Be the first!</li>';
493	}
