  position: fixed; left: 0; top: 0; z-index: 9999;
  width: 50px; height: 36px; pointer-events: none;
  transform-origin: 46px 18px; opacity: 0;
  transition: opacity 0.2s ease;
  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.35));
